local config = {
  str_homestory_N24diaoyu_90050101_1_dialog_content = "Vice!",
  str_homestory_N24diaoyu_90050101_2_dialog_content = "Oi, PlayerName.",
  str_homestory_N24diaoyu_90050101_3_dialog_content = "Você ainda gosta de pegar insetos ou coletar conchas para adicionar à sua coleção de espécimes?<sprite=emo_yihuo size=60 />",
  str_homestory_N24diaoyu_90050101_4_dialog_content = "Já não faço isso há algum tempo.",
  str_homestory_N24diaoyu_90050101_5_dialog_content = "Claro, existem muitas plantas e animais diferentes em Cloud Gardens, mas ainda envelhece depois de fazê-lo todos os dias do dia para a noite.",
  str_homestory_N24diaoyu_90050101_6_dialog_content = "Oh, todos os dias do dia para a noite? Você com certeza tem sido um com a natureza, não é, PlayerName?",
  str_homestory_N24diaoyu_90050101_7_dialog_content = "O que você planeja fazer a seguir?",
  str_homestory_N24diaoyu_90050101_8_dialog_content = "Que tal um museu que exiba todas as plantas e animais em Cloud Gardens para todos os visitantes aurorianos verem?",
  str_homestory_N24diaoyu_90050101_9_dialog_content = "<sprite=emo_dianzan size=60 />Essa é uma ótima ideia! Deixe-me pensar...",
  str_homestory_N24diaoyu_90050101_10_dialog_content = "Mas vai custar muito dinheiro.<sprite=emo_baiyebi size=60 />",
  str_homestory_N24diaoyu_90050101_11_dialog_content = "É claro. Um museu precisa de muitos equipamentos para proteger suas coleções.",
  str_homestory_N24diaoyu_90050101_12_dialog_content = "Como temperatura, sistemas de controle de umidade e...",
  str_homestory_N24diaoyu_90050101_13_dialog_content = "Espere. Isso foi Barton agora?",
  str_homestory_N24diaoyu_90050101_14_dialog_content = "Huh? Alguém passou por nós? Eu não estava prestando atenção.",
  str_homestory_N24diaoyu_90050101_15_dialog_content = "Deixa para lá. Eu provavelmente só vi algo no canto do meu olho que não estava lá.",
  str_homestory_N24diaoyu_90050101_16_dialog_content = "<sprite=emo_laba size=60 />PlayerName! PlayerName!",
  str_homestory_N24diaoyu_90050101_17_dialog_content = "Fia?",
  str_homestory_N24diaoyu_90050101_18_dialog_content = "Venha ajudar, PlayerName! Eu preciso que você me ajude com um monte de coisas!",
  str_homestory_N24diaoyu_90050101_19_dialog_content = "O que, você não vai nem fingir que tem um \"pequeno\" favor para pedir agora?",
  str_homestory_N24diaoyu_90050101_20_dialog_content = "Apenas vindo direto para mim com todos os seus problemas agora...<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050101_21_dialog_content = "Hum, pensei que já tínhamos passado de rodeios, PlayerName!",
  str_homestory_N24diaoyu_90050101_22_dialog_content = "Você tem razão. Então deixe-me rejeitá-lo aqui e agora.",
  str_homestory_N24diaoyu_90050101_23_dialog_content = "Huh? Por que!<sprite=emo_xinsui size=60 />",
  str_homestory_N24diaoyu_90050101_24_dialog_content = "Estou ocupado. Preciso construir um museu em Cloud Gardens.",
  str_homestory_N24diaoyu_90050101_25_dialog_content = "Isso é algo enorme para Cloud Gardens. Não tenho tempo para brincar com você.",
  str_homestory_N24diaoyu_90050101_26_dialog_content = "Ajudar-me é \"brincar\"!?",
  str_homestory_N24diaoyu_90050101_27_dialog_content = "<sprite=emo_shengqi size=60 />Ok PlayerName, não vou te ajudar da próxima vez, então! Você vai se arrepender disso, seu tolo!",
  str_homestory_N24diaoyu_90050101_28_dialog_content = "Ela fugiu. Está realmente certo deixar Fia sozinha assim?",
  str_homestory_N24diaoyu_90050101_29_dialog_content = "Não posso estragá-la fazendo tudo por ela.",
  str_homestory_N24diaoyu_90050101_30_dialog_content = "Em um ponto ou outro, ela precisará aprender a resolver as coisas sozinha. Vou dar um empurrão extra quando ela realmente precisar.",
  str_homestory_N24diaoyu_90050101_31_dialog_content = "É assim que ela cresce.",
  str_homestory_N24diaoyu_90050101_32_dialog_content = "<sprite=emo_chidai size=60 />Uau... Você está realmente se tornando um grande mentor, PlayerName.",
  str_homestory_N24diaoyu_90050101_33_dialog_content = "É isso ou é só conversa de sua parte.",
  str_homestory_N24diaoyu_90050101_34_dialog_content = "Hehehe...",
  str_homestory_N24diaoyu_90050101_35_dialog_content = "Huh? Fleur acabou de passar correndo?",
  str_homestory_N24diaoyu_90050101_36_dialog_content = "Barton, Fia e agora Fleur... Por que estão todos com pressa?",
  str_homestory_N24diaoyu_90050101_37_dialog_content = "Eu não suporto isso. Eu tenho que alcançá-los e ver o que está acontecendo.",
  str_homestory_N24diaoyu_90050102_1_dialog_content = "<sprite=emo_hanshui size=60 />Huff, puff!",
  str_homestory_N24diaoyu_90050102_2_dialog_content = "PlayerName, é melhor você respirar antes de desmaiar.",
  str_homestory_N24diaoyu_90050102_3_dialog_content = "Vício? PlayerName? Por que vocês dois estão ofegantes assim?",
  str_homestory_N24diaoyu_90050102_4_dialog_content = "Eu... estou tentando alcançar Fleur.",
  str_homestory_N24diaoyu_90050102_5_dialog_content = "E estou tentando ser um bom amigo para ele.",
  str_homestory_N24diaoyu_90050102_6_dialog_content = "Como... Como Fleur pode correr tão rápido? Ele não parece ser do tipo atlético.",
  str_homestory_N24diaoyu_90050102_7_dialog_content = "Sério? Na verdade, vejo Fleur correndo em Cloud Gardens com bastante frequência.",
  str_homestory_N24diaoyu_90050102_8_dialog_content = "O que? É quem ele realmente é? <sprite=emo_tanqi size=60 />Poderia ter me enganado...",
  str_homestory_N24diaoyu_90050102_9_dialog_content = "Então, por que você está atrás de Fleur, PlayerName?",
  str_homestory_N24diaoyu_90050102_10_dialog_content = "Ou... você está fazendo isso apenas por diversão?",
  str_homestory_N24diaoyu_90050102_11_dialog_content = "Para se divertir? De jeito nenhum!",
  str_homestory_N24diaoyu_90050102_12_dialog_content = "Bem... Não é como se houvesse algo importante. Só quero saber por que ele está com pressa.",
  str_homestory_N24diaoyu_90050102_13_dialog_content = "Essa é a própria definição de \"por diversão\", não é?<sprite=emo_xiaoku size=60 />",
  str_homestory_N24diaoyu_90050102_14_dialog_content = "Brincadeiras à parte, acho que sei o que Fleur está tramando.",
  str_homestory_N24diaoyu_90050102_15_dialog_content = "Sério? Você faz?",
  str_homestory_N24diaoyu_90050102_16_dialog_content = "Sim. A julgar pelo que está vestindo, provavelmente vai pescar.",
  str_homestory_N24diaoyu_90050102_17_dialog_content = "<sprite=emo_sikao size=60 />Pescaria...?",
  str_homestory_N24diaoyu_90050102_18_dialog_content = "Sim. Ouvi dizer que é um evento organizado em conjunto por um editor e muitas guildas de Umbraton, sugerido por um Rediesel Desert Aurorian.",
  str_homestory_N24diaoyu_90050102_19_dialog_content = "Este \"<color=#FFB400>Uma captura extraordinária</color>\" o concurso de pesca acaba sendo um grande sucesso. Os competidores são chamados <color=#FFB400>Pescadores</color>.",
  str_homestory_N24diaoyu_90050102_20_dialog_content = "Fleur deve ter entrado na competição e está tentando competir contra outros Pescadores.",
  str_homestory_N24diaoyu_90050102_21_dialog_content = "O grande prêmio desse tipo de evento deve ser um souvenir ou algo assim... Só não esperava que Fleur se interessasse por isso.",
  str_homestory_N24diaoyu_90050102_22_dialog_content = "Não acho que seja esse o caso. Diz-se que o prêmio é um <color=#FFB400>vara de pesca de ouro puro coberta com Lumamber</color>.",
  str_homestory_N24diaoyu_90050102_23_dialog_content = "Ouro puro, você diz...?",
  str_homestory_N24diaoyu_90050102_24_dialog_content = "E coberto com Lumamber...",
  str_homestory_N24diaoyu_90050102_25_dialog_content = "<sprite=emo_mojing size=60 />Aham! Carleen, você deve saber que as pessoas em Cloud Gardens me chamam de \"Pesqueiro Dragonwave\".",
  str_homestory_N24diaoyu_90050102_26_dialog_content = "Não vou deixar que tirem nenhum peixe de mim!",
  str_homestory_N24diaoyu_90050102_27_dialog_content = "(Se eu ganhar, terei dinheiro para construir um museu!<sprite=emo_baiyebi size=60 />)",
  str_homestory_N24diaoyu_90050102_28_dialog_content = "Você quer se juntar?",
  str_homestory_N24diaoyu_90050102_29_dialog_content = "Se o fizer, você terá que entrar em contato com Bethel, que representa as guildas que hospedam este evento...",
  str_homestory_N24diaoyu_90050102_30_dialog_content = "<sprite=emo_dianzan size=60 />Entendi! Obrigado, Carleen!",
  str_homestory_N24diaoyu_90050102_31_dialog_content = "Eu nem tinha terminado ainda.",
  str_homestory_N24diaoyu_90050102_32_dialog_content = "Bem... Por que não entramos no concurso com PlayerName?",
  str_homestory_N24diaoyu_90050102_33_dialog_content = "Hã?<sprite=emo_yihuo size=60 />",
  str_homestory_N24diaoyu_90050103_1_dialog_content = "Bethel!",
  str_homestory_N24diaoyu_90050103_2_dialog_content = "PlayerName, Vice. Ah, e Lady Carleen também!",
  str_homestory_N24diaoyu_90050103_3_dialog_content = "Há quanto tempo. Terminou o romance que recomendei, Vice?",
  str_homestory_N24diaoyu_90050103_4_dialog_content = "Quase! Eu gosto de como ele realmente mergulha nas emoções do protagonista!",
  str_homestory_N24diaoyu_90050103_5_dialog_content = "E sua relação com Genie, sua companheira mecânica, também é tocante!<sprite=emo_caitiao size=60 />",
  str_homestory_N24diaoyu_90050103_6_dialog_content = "<sprite=emo_aixin size=60 />Certo? Certo? Um relacionamento assim é tão platônico...",
  str_homestory_N24diaoyu_90050103_7_dialog_content = "Arram!",
  str_homestory_N24diaoyu_90050103_8_dialog_content = "Vice, não estamos aqui para conversar sobre a novela...",
  str_homestory_N24diaoyu_90050103_9_dialog_content = "Na verdade, estamos aqui porque queremos nos inscrever no concurso de pesca!",
  str_homestory_N24diaoyu_90050103_10_dialog_content = "Oh! Eu não sabia que vocês estavam todos interessados em pescar!",
  str_homestory_N24diaoyu_90050103_11_dialog_content = "Você esta brincando comigo? Eu sou o renomado Dragonwave Angler de Cloud Gardens!<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050103_12_dialog_content = "Estou muito interessado no grande prêmio!<sprite=emo_baiyebi size=60 />",
  str_homestory_N24diaoyu_90050103_13_dialog_content = "Bem... estou aqui porque eles estão.",
  str_homestory_N24diaoyu_90050103_14_dialog_content = "Eu vejo. Mas, desculpe, não ouvi nada sobre um Dragonwave Angler.",
  str_homestory_N24diaoyu_90050103_15_dialog_content = "Oh, o mundo saberá meu nome assim que eu levar para casa o grande prêmio!<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050103_16_dialog_content = "Certo... Isso seria algo pelo qual esperar. No entanto...",
  str_homestory_N24diaoyu_90050103_17_dialog_content = "Hum?",
  str_homestory_N24diaoyu_90050103_18_dialog_content = "O período de inscrição terminou.",
  str_homestory_N24diaoyu_90050103_19_dialog_content = "<sprite=emo_xinsui size=60 />O que!?",
  str_homestory_N24diaoyu_90050103_20_dialog_content = "PlayerName parece tão desapontado. É um grande golpe para ele não poder participar do concurso?",
  str_homestory_N24diaoyu_90050103_21_dialog_content = "Provavelmente... quero dizer, ele estava até tentando inventar nomes para o elenco.",
  str_homestory_N24diaoyu_90050103_22_dialog_content = "Bem... Existe uma maneira.",
  str_homestory_N24diaoyu_90050103_23_dialog_content = "Há uma maneira!?<sprite=emo_yihuo size=60 />",
  str_homestory_N24diaoyu_90050103_24_dialog_content = "Quer dizer, é um concurso que só vai ser divertido se houver muitos concorrentes.",
  str_homestory_N24diaoyu_90050103_25_dialog_content = "E também é meu trabalho garantir que bons pescadores tenham a chance de brilhar.",
  str_homestory_N24diaoyu_90050103_26_dialog_content = "Mas você terá que provar a si mesmo para mim primeiro.",
  str_homestory_N24diaoyu_90050103_27_dialog_content = "O que você está sugerindo?",
  str_homestory_N24diaoyu_90050103_28_dialog_content = "Cinco Knifefish por pessoa.",
  str_homestory_N24diaoyu_90050103_29_dialog_content = "O primeiro que voltar com cinco também ganha um presente surpresa!",
  str_homestory_N24diaoyu_90050103_30_dialog_content = "Entendi! Vamos, Vice, Carleen!",
  str_homestory_N24diaoyu_90050104_1_dialog_content = "Tem certeza de que tem o suficiente?",
  str_homestory_N24diaoyu_90050104_2_dialog_content = "Sim! ({1}/{2})",
  str_homestory_N24diaoyu_90050104_3_dialog_content = "Faltam apenas alguns. Um momento!",
  str_homestory_N24diaoyu_90050104_4_dialog_content = "Boa sorte!",
  str_homestory_N24diaoyu_90050104_5_dialog_content = "Bem, isso é rápido.",
  str_homestory_N24diaoyu_90050104_6_dialog_content = "<sprite=emo_dianzan size=60 />Parece PlayerName realmente não estava brincando.",
  str_homestory_N24diaoyu_90050104_7_dialog_content = "Heheh! É claro! Voltei aqui assim que peguei o peixe!",
  str_homestory_N24diaoyu_90050104_8_dialog_content = "Eles ainda não voltaram?",
  str_homestory_N24diaoyu_90050104_9_dialog_content = "Não. Bem, como prometido, você escolhe primeiro sua vara de pescar, PlayerName.",
  str_homestory_N24diaoyu_90050104_10_dialog_content = "Esse é o presente surpresa que você mencionou?",
  str_homestory_N24diaoyu_90050104_11_dialog_content = "Sim. Preparamos muitas varas de pesca diferentes para nossos competidores. Apenas um pescador aprovado consegue segurar uma de nossas varas de pesca certificadas.",
  str_homestory_N24diaoyu_90050104_12_dialog_content = "Então o que você vai ter? Uma vara de pescar fogo, água ou grama?",
  str_homestory_N24diaoyu_90050104_13_dialog_content = "Hum... Qual é a diferença?",
  str_homestory_N24diaoyu_90050104_14_dialog_content = "Você terá que descobrir por si mesmo! Talvez isso lhe dê uma habilidade especial ou cresça com você. Ou talvez não haja diferença alguma!",
  str_homestory_N24diaoyu_90050104_15_dialog_content = "Afinal, é apenas uma vara de pescar. Mas depois de escolher, ele se tornará seu melhor amigo.",
  str_homestory_N24diaoyu_90050104_16_dialog_content = "Depois eu escolho...",
  str_homestory_N24diaoyu_90050104_17_option_content = "A vara de pescar Grass!",
  str_homestory_N24diaoyu_90050104_18_option_content = "A vara de pesca Fire!",
  str_homestory_N24diaoyu_90050104_19_option_content = "A vara de pesca de água!",
  str_homestory_N24diaoyu_90050104_20_dialog_content = "Uau! É bom segurar!",
  str_homestory_N24diaoyu_90050104_21_dialog_content = "<sprite=emo_tanqi size=60 />Mas não acho que tenha nenhuma dessas habilidades especiais...",
  str_homestory_N24diaoyu_90050104_22_dialog_content = "Voltei.",
  str_homestory_N24diaoyu_90050104_23_dialog_content = "Você voltou, Carleen.",
  str_homestory_N24diaoyu_90050104_24_dialog_content = "Por favor, escolha uma vara de pescar entre as duas restantes.",
  str_homestory_N24diaoyu_90050104_25_dialog_content = "Tanto faz... Qualquer um serviria.",
  str_homestory_N24diaoyu_90050104_26_dialog_content = "Agora que você tem sua vara de pescar, por que não experimentá-la?",
  str_homestory_N24diaoyu_90050104_27_dialog_content = "Vamos começar a primeira rodada da competição enquanto esperamos que Vice volte.",
  str_homestory_N24diaoyu_90050104X_1_dialog_content = "PlayerName, sua vara de pesca parece poderosa.",
  str_homestory_N24diaoyu_90050104X_2_dialog_content = "Você está preparado para ter um concurso comigo primeiro?",
  str_homestory_N24diaoyu_90050104X_3_option_content = "Tô pronta.",
  str_homestory_N24diaoyu_90050104X_4_option_content = "Ainda não.",
  str_homestory_N24diaoyu_90050105_1_dialog_content = "Você é muito bom nisso, PlayerName.",
  str_homestory_N24diaoyu_90050105_2_dialog_content = "Você com certeza é um talento natural para a pesca, PlayerName.",
  str_homestory_N24diaoyu_90050105_3_dialog_content = "<sprite=emo_guilian size=60 />Heheh, não é só isso. Eu tinha muita prática em Cloud Gardens!",
  str_homestory_N24diaoyu_90050105_4_dialog_content = "(Isso, e muitas pessoas me pediram para pegar todos os tipos de peixes para eles.)",
  str_homestory_N24diaoyu_90050105_5_dialog_content = "Huh? Vocês são tão rápidos. Eu só peguei o suficiente agora.",
  str_homestory_N24diaoyu_90050105_6_dialog_content = "Tudo bem, Vice. Estamos todos esperando por você.",
  str_homestory_N24diaoyu_90050105_7_dialog_content = "Aqui está sua vara de pescar. Agora você é um Pescador!",
  str_homestory_N24diaoyu_90050105_8_dialog_content = "Então, estou ansioso para vê-lo no concurso—",
  str_homestory_N24diaoyu_90050105_9_dialog_content = "Para o campeão—",
  str_homestory_N24diaoyu_90050105_10_dialog_content = "Para o museu—",
  str_homestory_N24diaoyu_90050105_11_dialog_content = "Para o Lumamber—",
  str_homestory_N24diaoyu_90050105_12_dialog_content = "<sprite=emo_caitiao size=60 />Boa sorte!",
  str_homestory_N24diaoyu_90050201_1_dialog_content = "Certo. Agora que sou um pescador aprovado, começarei minha jornada para me tornar o campeão!",
  str_homestory_N24diaoyu_90050201_2_dialog_content = "Primeiras coisas primeiro!",
  str_homestory_N24diaoyu_90050201_3_dialog_content = "Hum... Primeira coisa...",
  str_homestory_N24diaoyu_90050201_4_dialog_content = "<sprite=emo_xiaoku size=60 />Acho que ainda não estou familiarizado com as regras.",
  str_homestory_N24diaoyu_90050201_5_dialog_content = "É embaraçoso. Indo atrás de Betel com perguntas depois desse tipo de discurso...",
  str_homestory_N24diaoyu_90050201_6_dialog_content = "Isso não é muito campeão.",
  str_homestory_N24diaoyu_90050201_7_dialog_content = "Todos devem saber sobre as regras, então é a mesma coisa se eu perguntar a outra pessoa! Certo!",
  str_homestory_N24diaoyu_90050201_8_dialog_content = "Hum? Não é a Lilica ali? Ela é de Umbraton e sabe-tudo.",
  str_homestory_N24diaoyu_90050201_9_dialog_content = "Eu deveria ir perguntar a ela.",
  str_homestory_N24diaoyu_90050202_1_dialog_content = "Lilica.",
  str_homestory_N24diaoyu_90050202_2_dialog_content = "<sprite=emo_laba size=60 />Lilica—",
  str_homestory_N24diaoyu_90050202_3_dialog_content = "Eh?!",
  str_homestory_N24diaoyu_90050202_4_dialog_content = "Você me assustou...",
  str_homestory_N24diaoyu_90050202_5_dialog_content = "Não esperava te encontrar aqui, PlayerName.",
  str_homestory_N24diaoyu_90050202_6_dialog_content = "Acabei de ter uma ideia extraordinária para uma cena!<sprite=emo_mojing size=60 />",
  str_homestory_N24diaoyu_90050202_7_dialog_content = "Desculpe me intrometer em seus pensamentos, então!",
  str_homestory_N24diaoyu_90050202_8_dialog_content = "Tudo bem. Minha inspiração estava se esgotando de qualquer maneira. Eu estava prestes a fazer uma pausa.",
  str_homestory_N24diaoyu_90050202_9_dialog_content = "Então, o que você precisa?",
  str_homestory_N24diaoyu_90050202_10_dialog_content = "Na verdade, você é um sabe-tudo por aqui.",
  str_homestory_N24diaoyu_90050202_11_dialog_content = "Oh? Isso é um belo elogio. Por que você está me bajulando?",
  str_homestory_N24diaoyu_90050202_12_dialog_content = "Você conhece um concurso de pesca chamado An Extraordinary Catch?",
  str_homestory_N24diaoyu_90050202_13_dialog_content = "Claro. É o que todo mundo está falando recentemente.",
  str_homestory_N24diaoyu_90050202_14_dialog_content = "Certo... Talvez eu possa escrever um roteiro sobre pesca.",
  str_homestory_N24diaoyu_90050202_15_dialog_content = "Os protagonistas são dois irmãos, e seu pai é professor. O irmão mais velho é um homem bom e honesto e herdou os negócios da família depois que se formou.",
  str_homestory_N24diaoyu_90050202_16_dialog_content = "E o irmão mais novo é romântico e adora a natureza. Ele aprendeu um método especial de pesca.",
  str_homestory_N24diaoyu_90050202_17_dialog_content = "No entanto, ele era viciado em jogos de azar e só conseguiu sair disso com a ajuda do irmão.",
  str_homestory_N24diaoyu_90050202_18_dialog_content = "E-espere um minuto... Você pode fazer isso mais tarde.",
  str_homestory_N24diaoyu_90050202_19_dialog_content = "Depois que você me contar sobre as regras do concurso, se você souber.",
  str_homestory_N24diaoyu_90050202_20_dialog_content = "Mas o irmão mais velho desapareceu e o irmão mais novo pegou um tubarão durante uma pescaria.",
  str_homestory_N24diaoyu_90050202_21_dialog_content = "Ele encontrou o corpo de seu irmão na barriga do tubarão, e isso se tornou um estranho caso de assassinato.",
  str_homestory_N24diaoyu_90050202_22_dialog_content = "Oh! Certo. Você está me perguntando sobre as regras. Claro, posso te ajudar.",
  str_homestory_N24diaoyu_90050202_23_dialog_content = "Sério?",
  str_homestory_N24diaoyu_90050202_24_dialog_content = "Mas você sabe como é. Você precisa fazer algo por mim.",
  str_homestory_N24diaoyu_90050202_25_dialog_content = "Junte um pouco de madeira para mim. Eu quero construir um conjunto.",
  str_homestory_N24diaoyu_90050202_26_dialog_content = "Certo. Eu volto já.",
  str_homestory_N24diaoyu_90050203_1_dialog_content = "Você encontrou a madeira? Estou realmente tentando criar um bom enredo aqui!",
  str_homestory_N24diaoyu_90050203_2_dialog_content = "Encontrei! ({1}/{2})",
  str_homestory_N24diaoyu_90050203_3_dialog_content = "Bom trabalho!",
  str_homestory_N24diaoyu_90050203_4_dialog_content = "Só um pouco mais. Volte a pensar por mais um tempo!",
  str_homestory_N24diaoyu_90050203_5_dialog_content = "Tudo bem, tudo bem. Apenas se apresse.",
  str_homestory_N24diaoyu_90050203_6_dialog_content = "Bom trabalho!",
  str_homestory_N24diaoyu_90050203_7_dialog_content = "É rápido.",
  str_homestory_N24diaoyu_90050203_8_dialog_content = "É claro. Eu sou um mestre em fazer recados agora!<sprite=emo_mojing size=60 />",
  str_homestory_N24diaoyu_90050203_9_dialog_content = "Você também foi bastante habilidoso anteriormente ao gravar o filme. Já pensou em fazer algum trabalho em locais de filmagem?",
  str_homestory_N24diaoyu_90050203_10_dialog_content = "<sprite=emo_hanshui size=60 />Hahaha... Vou pensar um pouco. Só espero que seja mais seguro da próxima vez.",
  str_homestory_N24diaoyu_90050203_11_dialog_content = "Hehe. Já que você é um mestre nisso, você também pode me trazer um pouco de peixe para o jantar?",
  str_homestory_N24diaoyu_90050203_12_dialog_content = "Um... Você arrecadou bastante com o último filme. Por que você precisa pescar para jantar em Cloud Gardens?",
  str_homestory_N24diaoyu_90050203_13_dialog_content = "Chama-se ser frugal! Estou guardando dinheiro para a continuação de Into the Haunted House.",
  str_homestory_N24diaoyu_90050203_14_dialog_content = "Multar. Vou apenas pensar nisso como um treino para o concurso. Apenas espere aqui por mim.",
  str_homestory_N24diaoyu_90050204_1_dialog_content = "Onde está meu jantar?",
  str_homestory_N24diaoyu_90050204_2_dialog_content = "Uau! Os peixes parecem muito animados. ({1}/{2})",
  str_homestory_N24diaoyu_90050204_3_dialog_content = "Só um pouco mais. Não é o suficiente, não é?",
  str_homestory_N24diaoyu_90050204_4_dialog_content = "Ah, ta tudo bem. Ainda não estou com fome. Você pode tentar pegar um pouco mais, PlayerName.",
  str_homestory_N24diaoyu_90050204_5_dialog_content = "<sprite=emo_caitiao size=60 />Uau! Isso é muito. Isso será suficiente por dias.",
  str_homestory_N24diaoyu_90050204_6_dialog_content = "Hmm... Você está planejando comer peixe todos os dias nos próximos dias?",
  str_homestory_N24diaoyu_90050204_7_dialog_content = "Também posso pedir a Cellulo para trazer algumas frutas para mim.",
  str_homestory_N24diaoyu_90050204_8_dialog_content = "(É melhor eu fazer o que a Lilica manda.)",
  str_homestory_N24diaoyu_90050204_9_dialog_content = "(Não quero magoá-la dizendo o que penso.)",
  str_homestory_N24diaoyu_90050204_10_dialog_content = "Então... E as regras?",
  str_homestory_N24diaoyu_90050204_11_dialog_content = "Certo! Quase esqueci.",
  str_homestory_N24diaoyu_90050204_12_dialog_content = "Você não está brincando comigo, está?<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050204_13_dialog_content = "Brincando! Eu só estou brincando!",
  str_homestory_N24diaoyu_90050204_14_dialog_content = "Na verdade, eu mesmo não conheço as regras, mas conheço alguém que conhece.",
  str_homestory_N24diaoyu_90050204_15_dialog_content = "Você também precisará passar por ela para se tornar um verdadeiro pescador.",
  str_homestory_N24diaoyu_90050204_16_dialog_content = "Como assim?",
  str_homestory_N24diaoyu_90050204_17_dialog_content = "Fia. Ela é a instrutora e especialista oficial do concurso.",
  str_homestory_N24diaoyu_90050204_18_dialog_content = "O que... Fia? Acabei de recusar o pedido dela não faz muito tempo...",
  str_homestory_N24diaoyu_90050204_19_dialog_content = "Hum? Aconteceu algo entre vocês dois?",
  str_homestory_N24diaoyu_90050204_20_dialog_content = "Ela não deveria ser do tipo que guarda rancor, certo? Apenas fale com ela.",
  str_homestory_N24diaoyu_90050204_21_dialog_content = "Sim você está certo!",
  str_homestory_N24diaoyu_90050204_22_dialog_content = "Bem, obrigada, Lilica! Vejo você mais tarde!<sprite=emo_woshou size=60 />",
  str_homestory_N24diaoyu_90050205_1_dialog_content = "Ei, Fia—",
  str_homestory_N24diaoyu_90050205_2_dialog_content = "<sprite=emo_emo size=60 />Bem, este não é o Sr. Curador do Museu, PlayerName?",
  str_homestory_N24diaoyu_90050205_3_dialog_content = "Pensei que você fosse um homem ocupado.",
  str_homestory_N24diaoyu_90050205_4_dialog_content = "Hmm... Você ainda está chateado?",
  str_homestory_N24diaoyu_90050205_5_dialog_content = "(É hora de tomar a iniciativa de se desculpar!)",
  str_homestory_N24diaoyu_90050205_6_dialog_content = "<sprite=emo_tanqi size=60 />Sinto muito por mais cedo. O erro foi meu, e aprendi com meu erro!",
  str_homestory_N24diaoyu_90050205_7_dialog_content = "Hum! Então você não está dando desculpas. Bom.",
  str_homestory_N24diaoyu_90050205_8_dialog_content = "Você está aqui por causa do concurso, não é?",
  str_homestory_N24diaoyu_90050205_9_dialog_content = "Isso mesmo. Eu sabia que você não guardaria rancor, Fia!<sprite=emo_dianzan size=60 />",
  str_homestory_N24diaoyu_90050205_10_dialog_content = "Não me agradeça ainda. Eu não disse que vou te ajudar.",
  str_homestory_N24diaoyu_90050205_11_dialog_content = "Se você quiser entrar na competição, você tem que me vencer primeiro.",
  str_homestory_N24diaoyu_90050205_12_dialog_content = "Agora, PlayerName, mostre-me o que você obteve!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050205X_1_dialog_content = "Já podemos começar? Eu sou uma pessoa muito ocupada.",
  str_homestory_N24diaoyu_90050205X_2_option_content = "Sim!",
  str_homestory_N24diaoyu_90050205X_3_option_content = "De repente, lembrei-me de que havia algo que precisava fazer!",
  str_homestory_N24diaoyu_90050206_1_dialog_content = "Hum...! Fia, não esperava que você fosse tão boa.",
  str_homestory_N24diaoyu_90050206_2_dialog_content = "Huh? Nada mal. Nada mal. Estou impressionado, um pouco. Você passou.",
  str_homestory_N24diaoyu_90050206_3_dialog_content = "Agora me sinto um pouco melhor depois de algum exercício.",
  str_homestory_N24diaoyu_90050206_4_dialog_content = "Eu vou te perdoar por mais cedo, então.",
  str_homestory_N24diaoyu_90050206_5_dialog_content = "Mas, não pense que dei o meu melhor. Eu te deixo fácil.",
  str_homestory_N24diaoyu_90050206_6_dialog_content = "Você me deixou escapar facilmente? Você é incrível, Fia!<sprite=emo_dianzan size=60 />",
  str_homestory_N24diaoyu_90050206_7_dialog_content = "Oh, agora você está apenas sendo um lambe-botas!",
  str_homestory_N24diaoyu_90050206_8_dialog_content = "É melhor você dedicar algum tempo se quiser se tornar o campeão.",
  str_homestory_N24diaoyu_90050206_9_dialog_content = "Agora, vá em frente e bata três <color=#FFB400>Mestres Pescadores</color>!",
  str_homestory_N24diaoyu_90050206_10_dialog_content = "A porta para o campeonato só será aberta após você derrotar três Mestres Pescadores.",
  str_homestory_N24diaoyu_90050206_11_dialog_content = "Aguardo seus resultados.",
  str_homestory_N24diaoyu_90050206_12_dialog_content = "Entendido!",
  str_homestory_N24diaoyu_90050301_1_dialog_content = "Ei, PlayerName!",
  str_homestory_N24diaoyu_90050301_2_dialog_content = "Brock? O que faz aqui?",
  str_homestory_N24diaoyu_90050301_3_dialog_content = "O mesmo de antes. Sem novidades. Treino diário, claro.<sprite=emo_yaling size=60 />",
  str_homestory_N24diaoyu_90050301_4_dialog_content = "Tenho treinado incansavelmente todos os dias para me preparar para o trono da Rediesel Wrench.",
  str_homestory_N24diaoyu_90050301_5_dialog_content = "Certo... Vou me despedir de você então...",
  str_homestory_N24diaoyu_90050301_6_dialog_content = "Espere um minuto.",
  str_homestory_N24diaoyu_90050301_7_dialog_content = "Ei, PlayerName, segure-o. Você não sente que está faltando algo em Cloud Gardens?",
  str_homestory_N24diaoyu_90050301_8_dialog_content = "Hum? O que está a faltar?",
  str_homestory_N24diaoyu_90050301_9_dialog_content = "Se você está propondo algo, tenho certeza que é inútil.<sprite=emo_xiaoku size=60 />",
  str_homestory_N24diaoyu_90050301_10_dialog_content = "<sprite=emo_shengqi size=60 />Ei! PlayerName! Como você pode dizer aquilo? Eu não sou seu melhor amigo?",
  str_homestory_N24diaoyu_90050301_11_dialog_content = "Estou falando muito sério! O mínimo que você pode fazer é ouvir!",
  str_homestory_N24diaoyu_90050301_12_dialog_content = "Bem bem. Vá em frente.",
  str_homestory_N24diaoyu_90050301_13_dialog_content = "Aham! Você não acha que precisamos de grandes instalações de treinamento físico aqui?",
  str_homestory_N24diaoyu_90050301_14_dialog_content = "Para um atleta como eu, Cloud Gardens é solitário e chato.",
  str_homestory_N24diaoyu_90050301_15_dialog_content = "Por que você simplesmente não encontra um prédio e corre ao redor dele?",
  str_homestory_N24diaoyu_90050301_16_dialog_content = "Isso é aeróbico. O que eu preciso é de treinamento de resistência de alta intensidade!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050301_17_dialog_content = "<sprite=emo_yihuo size=60 />Alta intensidade... re-que treinamento?",
  str_homestory_N24diaoyu_90050301_18_dialog_content = "Apenas me consiga alguns minérios e construirei as máquinas de treinamento para você!",
  str_homestory_N24diaoyu_90050301_19_dialog_content = "Huh? Sem chance. Agora estou ocupado!",
  str_homestory_N24diaoyu_90050301_20_dialog_content = "Ocupado fazendo o quê? Você está ocupado tentando rastrear um Mestre Pescador, não é?",
  str_homestory_N24diaoyu_90050301_21_dialog_content = "Como você sabia?",
  str_homestory_N24diaoyu_90050301_22_dialog_content = "Tudo o que você precisa saber é: você me ajuda e eu ajudo você.",
  str_homestory_N24diaoyu_90050301_23_dialog_content = "Tudo bem... vou confiar em você.",
  str_homestory_N24diaoyu_90050302_1_dialog_content = "Você tem o suficiente? Mal posso esperar!",
  str_homestory_N24diaoyu_90050302_2_dialog_content = "Bom! Eles estão todos aqui. ({1}/{2})",
  str_homestory_N24diaoyu_90050302_3_dialog_content = "Só um pouco mais. Espere mais um pouco.",
  str_homestory_N24diaoyu_90050302_4_dialog_content = "Vamos! Meu sangue está fervendo agora!",
  str_homestory_N24diaoyu_90050302_5_dialog_content = "Bem, devo dizer, você está em boa forma, PlayerName.",
  str_homestory_N24diaoyu_90050302_6_dialog_content = "Pare de brincar comigo. Apenas me diga o que eu preciso saber sobre o concurso!",
  str_homestory_N24diaoyu_90050302_7_dialog_content = "Não se preocupe, eu vou te dizer. Fleur é uma pescadora mestre.",
  str_homestory_N24diaoyu_90050302_8_dialog_content = "O que? Fleur é uma pescadora mestre? Achei que a Rediesel Wrench fosse baseada no deserto...",
  str_homestory_N24diaoyu_90050302_9_dialog_content = "E daí? Então eles não são bons em pescar minhocas e coisas assim?",
  str_homestory_N24diaoyu_90050302_10_dialog_content = "É melhor não subestimá-lo só porque ele é membro da Rediesel Wrench.",
  str_homestory_N24diaoyu_90050302_11_dialog_content = "Aprendi isso por experiência.",
  str_homestory_N24diaoyu_90050302_12_dialog_content = "OK. Vou ver Fleur, então.",
  str_homestory_N24diaoyu_90050302_13_dialog_content = "Mais tarde!",
  str_homestory_N24diaoyu_90050303_1_dialog_content = "Fleur!",
  str_homestory_N24diaoyu_90050303_2_dialog_content = "Ei, PlayerName.",
  str_homestory_N24diaoyu_90050303_3_dialog_content = "Você está aqui para o evento de degustação?",
  str_homestory_N24diaoyu_90050303_4_dialog_content = "<sprite=emo_yihuo size=60 />Que evento de degustação?",
  str_homestory_N24diaoyu_90050303_5_dialog_content = "Eu ouvi de Brock que você é um pescador mestre. Estou aqui para te desafiar!",
  str_homestory_N24diaoyu_90050303_6_dialog_content = "Certo. Eu me inscrevi para esse evento, que dá uma vara de pescar de graça, para coletar ingredientes alimentares, e consegui alguns peixes...",
  str_homestory_N24diaoyu_90050303_7_dialog_content = "Acho que foi assim que me tornei um Mestre Pescador.",
  str_homestory_N24diaoyu_90050303_8_dialog_content = "Dizendo isso como se não fosse nada, entendo que você realmente é uma boa pescadora, Fleur.",
  str_homestory_N24diaoyu_90050303_9_dialog_content = "Bem, não vamos esperar! PlayerName o Dragonwave Angler desafia você!<sprite=emo_mojing size=60 />",
  str_homestory_N24diaoyu_90050303_10_dialog_content = "Agora não é a hora. Desculpe.",
  str_homestory_N24diaoyu_90050303_11_dialog_content = "Mas por quê?",
  str_homestory_N24diaoyu_90050303_12_dialog_content = "Como eu disse, estou preparando os ingredientes da comida para o evento de degustação.<sprite=emo_rou size=60 />",
  str_homestory_N24diaoyu_90050303_13_dialog_content = "Este é um novo método de cozimento que acabei de aprender.",
  str_homestory_N24diaoyu_90050303_14_dialog_content = "Servir frutos do mar frescos com o mínimo de tempero para preservar o sabor original dos ingredientes alimentares.",
  str_homestory_N24diaoyu_90050303_15_dialog_content = "No entanto, eu simplesmente não tenho ingredientes alimentares suficientes. Que dor de cabeça.",
  str_homestory_N24diaoyu_90050303_16_dialog_content = "Eu ajudo!",
  str_homestory_N24diaoyu_90050303_17_dialog_content = "Sério? Você faria isso por mim?",
  str_homestory_N24diaoyu_90050303_18_dialog_content = "Se você estiver disposto a ajudar, vou me certificar de prepará-lo para que possamos começar nossa pequena competição. Como é isso, PlayerName?",
  str_homestory_N24diaoyu_90050303_19_dialog_content = "Traga-me um pouco de baiacu. Você pode pensar nisso como um aquecimento, PlayerName.",
  str_homestory_N24diaoyu_90050303_20_dialog_content = "Deixa comigo.",
  str_homestory_N24diaoyu_90050304_1_dialog_content = "Você conseguiu baiacu suficiente?",
  str_homestory_N24diaoyu_90050304_2_dialog_content = "Sim! ({1}/{2})",
  str_homestory_N24diaoyu_90050304_3_dialog_content = "Apenas mais alguns. Você vai pegá-los em breve!",
  str_homestory_N24diaoyu_90050304_4_dialog_content = "OK. Muito obrigado.",
  str_homestory_N24diaoyu_90050304_5_dialog_content = "Obrigada, PlayerName.",
  str_homestory_N24diaoyu_90050304_6_dialog_content = "Esses peixes com certeza são frescos e vivos.",
  str_homestory_N24diaoyu_90050304_7_dialog_content = "Como você vai preparar o peixe?",
  str_homestory_N24diaoyu_90050304_8_dialog_content = "Bem... peixes diferentes requerem métodos diferentes.",
  str_homestory_N24diaoyu_90050304_9_dialog_content = "Alguns precisam ser desossados, e a cabeça e os órgãos internos que não são adequados para alimentação também precisam ser removidos primeiro.",
  str_homestory_N24diaoyu_90050304_10_dialog_content = "Então posso cortar a bela carne e infundi-la com Lumina para matar os parasitas lá dentro.",
  str_homestory_N24diaoyu_90050304_11_dialog_content = "Você pode usar o Lumina para isso!?<sprite=emo_cangshu size=60 />",
  str_homestory_N24diaoyu_90050304_12_dialog_content = "Sim. É algo que acabei de aprender também.",
  str_homestory_N24diaoyu_90050304_13_dialog_content = "Quanto ao baiacu que você acabou de trazer, preciso remover com cuidado os órgãos internos, os olhos e até o sangue.",
  str_homestory_N24diaoyu_90050304_14_dialog_content = "Na verdade, agora que penso nisso, deve haver algumas pessoas no evento que se ressentem de peixe cru.",
  str_homestory_N24diaoyu_90050304_15_dialog_content = "Comê-lo cru também pode causar indigestão em algumas pessoas.",
  str_homestory_N24diaoyu_90050304_16_dialog_content = "Eu me pergunto se você pode me trazer um pouco de água fresca, PlayerName?",
  str_homestory_N24diaoyu_90050304_17_dialog_content = "Seria perfeito se eu pudesse preparar uma sopa de peixe para todos.<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050304_18_dialog_content = "Entendido.",
  str_homestory_N24diaoyu_90050305_1_dialog_content = "Você tem a água?",
  str_homestory_N24diaoyu_90050305_2_dialog_content = "Sim, está feito! ({1}/{2})",
  str_homestory_N24diaoyu_90050305_3_dialog_content = "Ainda não. Me dê um minuto.",
  str_homestory_N24diaoyu_90050305_4_dialog_content = "Claro. Obrigada.",
  str_homestory_N24diaoyu_90050305_5_dialog_content = "Obrigado um milhão. Você vai ter que me esperar um pouco. Depois que a comida estiver preparada, você quer experimentá-la primeiro?",
  str_homestory_N24diaoyu_90050305_6_dialog_content = "Sério? Eu não tinha meu - espere, estou aqui para desafiá-lo!",
  str_homestory_N24diaoyu_90050305_7_dialog_content = "Isso pode ser verdade, PlayerName. Por favor, escolha um para fazer primeiro, comer ou competir?",
  str_homestory_N24diaoyu_90050305_8_option_content = "Comer",
  str_homestory_N24diaoyu_90050305_9_dialog_content = "Excelente. Por favor, espere aqui. A comida deve ficar pronta em duas horas.",
  str_homestory_N24diaoyu_90050305_10_dialog_content = "Tanto tempo? Vamos fazer a competição primeiro!",
  str_homestory_N24diaoyu_90050305_11_option_content = "Competir",
  str_homestory_N24diaoyu_90050305_12_dialog_content = "Eu vejo. Se é isso que você quer, então vamos começar!",
  str_homestory_N24diaoyu_90050305X1_1_dialog_content = "Podemos começar agora? Ou você quer comer alguma coisa primeiro?",
  str_homestory_N24diaoyu_90050305X1_2_option_content = "Vamos!",
  str_homestory_N24diaoyu_90050305X1_3_option_content = "Espere um segundo...",
  str_homestory_N24diaoyu_90050306_1_dialog_content = "<sprite=emo_xuanyun size=60 />Ufa... Quase perdido.",
  str_homestory_N24diaoyu_90050306_2_dialog_content = "Hahaha! PlayerName, Você está muito bem!<sprite=emo_dianzan size=60 />",
  str_homestory_N24diaoyu_90050306_3_dialog_content = "Admito minha derrota. Você me venceu justo e quadrado.",
  str_homestory_N24diaoyu_90050306_4_dialog_content = "Justo e quadrado, realmente? Agora você está me deixando desconfiado.",
  str_homestory_N24diaoyu_90050306_5_dialog_content = "Sem chance. Esta é uma competição honrosa. Eu estava falando muito sério sobre isso.",
  str_homestory_N24diaoyu_90050306_6_dialog_content = "De qualquer forma, você derrotou um Mestre Pescador agora.",
  str_homestory_N24diaoyu_90050401_1_dialog_content = "Agora que descansei um pouco, devo procurar o próximo Mestre Pescador.",
  str_homestory_N24diaoyu_90050401_2_dialog_content = "Hmm... Eu deveria olhar em volta e reunir algumas informações primeiro.",
  str_homestory_N24diaoyu_90050401_3_dialog_content = "Ei, PlayerName!",
  str_homestory_N24diaoyu_90050401_4_dialog_content = "Oi, Barton. O que é isso?",
  str_homestory_N24diaoyu_90050401_5_dialog_content = "Ouvi dizer que você também é pescador, certo?",
  str_homestory_N24diaoyu_90050401_6_dialog_content = "Você até derrotou Fleur, uma pescadora mestre. Nada mal. Nada mal.",
  str_homestory_N24diaoyu_90050401_7_dialog_content = "Agradeço pelo elogio.",
  str_homestory_N24diaoyu_90050401_8_dialog_content = "Não quero parecer arrogante, mas sei uma ou duas coisas sobre pesca.",
  str_homestory_N24diaoyu_90050401_9_dialog_content = "Se for assim, vamos fazer uma pequena competição amigável.",
  str_homestory_N24diaoyu_90050401_10_dialog_content = "Deve realmente me ajudar aprender uma ou duas lições com você.",
  str_homestory_N24diaoyu_90050401_11_dialog_content = "Oh? Você também se inscreveu no concurso?",
  str_homestory_N24diaoyu_90050401_12_dialog_content = "Isso mesmo. Como fundador da Marinha Illumina, a pesca é uma habilidade necessária.",
  str_homestory_N24diaoyu_90050401_13_dialog_content = "Venha, PlayerName. Vamos ver o que você tem.",
  str_homestory_N24diaoyu_90050401_14_dialog_content = "Eu não vou pegar leve com você!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050401_15_dialog_content = "<sprite=emo_daomei size=60 />Droga... Não esperava que Barton fosse tão bom nisso.",
  str_homestory_N24diaoyu_90050401_16_dialog_content = "Parece que você tem um longo caminho a percorrer, fracote.<sprite=emo_gezitou size=60 />",
  str_homestory_N24diaoyu_90050401_17_dialog_content = "Você não tem convicção em lançar e cambalear.",
  str_homestory_N24diaoyu_90050401_18_dialog_content = "O mais importante é que você está cheio de dúvidas.",
  str_homestory_N24diaoyu_90050401_19_dialog_content = "Se você não pudesse me derrotar, você não seria capaz de derrotar outros Mestres Pescadores.",
  str_homestory_N24diaoyu_90050401_20_dialog_content = "Se isso é apenas um jogo para você, é melhor desistir agora!",
  str_homestory_N24diaoyu_90050401_21_dialog_content = "<sprite=emo_tanqi size=60 />Eu... Como é possível que eu tenha perdido?",
  str_homestory_N24diaoyu_90050401_22_dialog_content = "Eu até superei Fleur...",
  str_homestory_N24diaoyu_90050401_23_dialog_content = "Mas não posso negar que Barton é realmente um profissional nisso.",
  str_homestory_N24diaoyu_90050401_24_dialog_content = "Eu preciso ser melhor! Mas como eu melhoro?",
  str_homestory_N24diaoyu_90050401_25_dialog_content = "Cara...",
  str_homestory_N24diaoyu_90050401_26_dialog_content = "Ei, este não é o meu pequeno celestita?",
  str_homestory_N24diaoyu_90050401_27_dialog_content = "Ah, Azure...",
  str_homestory_N24diaoyu_90050401_28_dialog_content = "Por que o rosto comprido? Alguém te intimidou?",
  str_homestory_N24diaoyu_90050401_29_dialog_content = "Eu... Perdi a competição de pesca para o Barton.",
  str_homestory_N24diaoyu_90050401_30_dialog_content = "Então... você também se inscreveu no concurso?",
  str_homestory_N24diaoyu_90050401_31_dialog_content = "Sim. Mas não sou bom o suficiente para vencer.",
  str_homestory_N24diaoyu_90050401_32_dialog_content = "Fiquei tão cheio de mim só porque superei Fleur.",
  str_homestory_N24diaoyu_90050401_33_dialog_content = "Mas, na verdade, não sou nem de longe um profissional...",
  str_homestory_N24diaoyu_90050401_34_dialog_content = "Tudo bem, tudo bem. Você já ouviu um ditado que diz: \"o mau humor espanta os peixes\"?",
  str_homestory_N24diaoyu_90050401_35_dialog_content = "Nunca. Você acabou de inventar, não foi?",
  str_homestory_N24diaoyu_90050401_36_dialog_content = "Hahaha! Você me pegou, pequena celestita.<sprite=emo_aixin size=60 />",
  str_homestory_N24diaoyu_90050401_37_dialog_content = "Por que você não me faz um favor? Vá dar um passeio, ou simplesmente vá fazer alguma coisa. Nada.",
  str_homestory_N24diaoyu_90050401_38_dialog_content = "Que tal me trazer um pouco de água?",
  str_homestory_N24diaoyu_90050401_39_dialog_content = "Água? Para que você precisa de água?",
  str_homestory_N24diaoyu_90050401_40_dialog_content = "Não pergunte. Apenas me faça este favor.",
  str_homestory_N24diaoyu_90050402_1_dialog_content = "Você tem a água?",
  str_homestory_N24diaoyu_90050402_2_dialog_content = "Bom. ({1}/{2})",
  str_homestory_N24diaoyu_90050402_3_dialog_content = "Bem, você é rápido.",
  str_homestory_N24diaoyu_90050402_4_dialog_content = "Não...",
  str_homestory_N24diaoyu_90050402_5_dialog_content = "Alegrar. Prometa-me que vai buscar a água primeiro.",
  str_homestory_N24diaoyu_90050402_6_dialog_content = "Agora, coloque a água para baixo. Como você se sente agora?",
  str_homestory_N24diaoyu_90050402_7_dialog_content = "Hmm... Não tão chateado quanto antes.",
  str_homestory_N24diaoyu_90050402_8_dialog_content = "Uh-huh. Você sabe por que o Cloud Gardens foi escolhido como local do concurso?",
  str_homestory_N24diaoyu_90050402_9_dialog_content = "Bem... Porque não me importo que haja um concurso de pesca aqui?",
  str_homestory_N24diaoyu_90050402_10_dialog_content = "Essa é uma das razões, mas não a razão.",
  str_homestory_N24diaoyu_90050402_11_dialog_content = "É porque os peixes aqui em Cloud Gardens são diferentes dos de qualquer outro lugar.",
  str_homestory_N24diaoyu_90050402_12_dialog_content = "Eles podem sentir emoções próximas. Se você não estiver focado ou determinado, eles podem sentir isso e ficar alertas.",
  str_homestory_N24diaoyu_90050402_13_dialog_content = "É por isso que este local foi escolhido para realizar o concurso.",
  str_homestory_N24diaoyu_90050402_14_dialog_content = "E essa também é a razão pela qual você perdeu para Barton.",
  str_homestory_N24diaoyu_90050402_15_dialog_content = "Você não tem convicção e foco.",
  str_homestory_N24diaoyu_90050402_16_dialog_content = "Este concurso testa não apenas sua técnica, mas também sua determinação e comprometimento.",
  str_homestory_N24diaoyu_90050402_17_dialog_content = "E-é isso?",
  str_homestory_N24diaoyu_90050402_18_dialog_content = "Barton também disse algo semelhante agora.",
  str_homestory_N24diaoyu_90050402_19_dialog_content = "Eu quero ser melhor!<sprite=emo_yaling size=60 />",
  str_homestory_N24diaoyu_90050402_20_dialog_content = "Você disse isso tão bem.",
  str_homestory_N24diaoyu_90050402_21_dialog_content = "Venha... pequena celestita.",
  str_homestory_N24diaoyu_90050402_22_dialog_content = "Vou te ensinar a segurar a vara corretamente.",
  str_homestory_N24diaoyu_90050402_23_dialog_content = "E-espere! Você está chegando muito perto!",
  str_homestory_N24diaoyu_90050402_24_dialog_content = "Você deve ser paciente. Esta é uma lição muito séria.",
  str_homestory_N24diaoyu_90050402_25_dialog_content = "Você tem muito a aprender para se tornar o campeão!",
  str_homestory_N24diaoyu_90050402_26_dialog_content = "Bem... Devo dizer que o Azure me ensinou bastante sobre pesca.",
  str_homestory_N24diaoyu_90050402_27_dialog_content = "Vou desafiar Barton novamente, agora mesmo!",
  str_homestory_N24diaoyu_90050403_1_dialog_content = "Oh, você está de volta, fracote.<sprite=emo_gezitou size=60 />",
  str_homestory_N24diaoyu_90050403_2_dialog_content = "Isso é uma boa aparência. Parece que você tem o que é preciso agora.",
  str_homestory_N24diaoyu_90050403_3_dialog_content = "Isso mesmo. O velho eu está morto. Eu sou o novo eu!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050403_4_dialog_content = "Você quer fazer isso de novo?",
  str_homestory_N24diaoyu_90050403_5_option_content = "Vamos nessa!",
  str_homestory_N24diaoyu_90050403_6_option_content = "Eu não estou pronto ainda.",
  str_homestory_N24diaoyu_90050404_1_dialog_content = "Eca! Eu perdi!",
  str_homestory_N24diaoyu_90050404_2_dialog_content = "Não esperava que você pudesse crescer tanto em tão pouco tempo.",
  str_homestory_N24diaoyu_90050404_3_dialog_content = "<sprite=emo_woshou size=60 />Tenho que admitir que você é melhor do que eu agora.",
  str_homestory_N24diaoyu_90050404_4_dialog_content = "Regras são regras... Eu te dou o dinheiro que eu...",
  str_homestory_N24diaoyu_90050404_5_dialog_content = "Espere um minuto! Não existem regras assim! Isso não é como a luta de feras maravilhosas!",
  str_homestory_N24diaoyu_90050404_6_dialog_content = "Ah... Você está certo.",
  str_homestory_N24diaoyu_90050404_7_dialog_content = "Então, eu vou te dizer onde você pode encontrar o próximo Mestre Pescador.",
  str_homestory_N24diaoyu_90050405_1_dialog_content = "Este deve ser o lugar onde Barton me disse para ir.",
  str_homestory_N24diaoyu_90050405_2_dialog_content = "Hum? Por que você está aqui, pequena celestita?",
  str_homestory_N24diaoyu_90050405_3_dialog_content = "Você já derrotou Barton?",
  str_homestory_N24diaoyu_90050405_4_dialog_content = "Sim! Graças a você, superei Barton!",
  str_homestory_N24diaoyu_90050405_5_dialog_content = "Essas são ótimas notícias.",
  str_homestory_N24diaoyu_90050405_6_dialog_content = "Você sabe que me deve uma, certo?",
  str_homestory_N24diaoyu_90050405_7_dialog_content = "Heheh! Eu prometo que não vou esquecer.",
  str_homestory_N24diaoyu_90050405_8_dialog_content = "A propósito, aquele de quem Barton falou deveria estar aqui... mas onde?",
  str_homestory_N24diaoyu_90050405_9_dialog_content = "Você está olhando para ela.",
  str_homestory_N24diaoyu_90050405_10_dialog_content = "Hã? O qu...",
  str_homestory_N24diaoyu_90050405_11_dialog_content = "Isso é exatamente o que quero dizer.",
  str_homestory_N24diaoyu_90050405_12_dialog_content = "O que? Espero que seu espírito não seja tão facilmente amortecido.",
  str_homestory_N24diaoyu_90050405_13_dialog_content = "Não... Pensei na possibilidade de ser você.",
  str_homestory_N24diaoyu_90050405_14_dialog_content = "Mas não. Estou confiante e comprometido. Vamos competir!<sprite=emo_woshou size=60 />",
  str_homestory_N24diaoyu_90050405_15_dialog_content = "Estou tão aliviada.",
  str_homestory_N24diaoyu_90050405_16_dialog_content = "Deixe-me ver o quanto você melhorou.",
  str_homestory_N24diaoyu_90050405X_1_option_content = "Bem, eu não vou esconder nada, então... Vamos lá!",
  str_homestory_N24diaoyu_90050405X_2_option_content = "Não, ainda tenho que praticar um pouco mais.",
  str_homestory_N24diaoyu_90050406_6_dialog_content = "Bem, bem, eu pensei que você me devia um favor, mas você realmente não hesitou.",
  str_homestory_N24diaoyu_90050406_7_dialog_content = "Porque eu sei que você não gostaria que eu pegasse leve com você, especialmente em uma competição.",
  str_homestory_N24diaoyu_90050406_8_dialog_content = "Isso mesmo. São duas coisas diferentes.",
  str_homestory_N24diaoyu_90050406_9_dialog_content = "Mas estou realmente impressionado com a forma como você foi capaz de me vencer. Bem feito.",
  str_homestory_N24diaoyu_90050406_10_dialog_content = "E que você não está mais incomodado ou afetado por outras coisas.",
  str_homestory_N24diaoyu_90050406_11_dialog_content = "<sprite=emo_caitiao size=60 />Parabéns. Você derrotou dois Mestres Pescadores. Agora você é um grande pescador.",
  str_homestory_N24diaoyu_90050501_1_dialog_content = "Certo. Eu venci dois Mestres Pescadores.",
  str_homestory_N24diaoyu_90050501_2_dialog_content = "Apesar de alguns contratempos, ainda estou progredindo bem.",
  str_homestory_N24diaoyu_90050501_3_dialog_content = "Agora, tudo o que preciso é derrotar um último Mestre Pescador para vencer!",
  str_homestory_N24diaoyu_90050501_4_dialog_content = "Eu deveria reunir algumas informações sobre o último Mestre Pescador.",
  str_homestory_N24diaoyu_90050501_5_dialog_content = "<sprite=emo_tanqi size=60 />*Suspiros*",
  str_homestory_N24diaoyu_90050501_6_dialog_content = "Huh? Aquela voz?",
  str_homestory_N24diaoyu_90050501_7_dialog_content = "Axélia? Por que você está aqui suspirando assim?",
  str_homestory_N24diaoyu_90050501_8_dialog_content = "PlayerName...",
  str_homestory_N24diaoyu_90050501_9_dialog_content = "Isso é uma vara de pescar em você? Então você também é um...",
  str_homestory_N24diaoyu_90050501_10_dialog_content = "Isso mesmo. Eu sou o Pescador Dragonwave!<sprite=emo_mojing size=60 />",
  str_homestory_N24diaoyu_90050501_11_dialog_content = "Agradável.",
  str_homestory_N24diaoyu_90050501_12_dialog_content = "Estou com ciúmes.",
  str_homestory_N24diaoyu_90050501_13_dialog_content = "Ciumento de como você é saudável e capaz de participar de um concurso de pesca, PlayerName.",
  str_homestory_N24diaoyu_90050501_14_dialog_content = "Estou com muito ciúme.",
  str_homestory_N24diaoyu_90050501_15_dialog_content = "Hum... Por que você simplesmente não se inscreve se quiser participar também?",
  str_homestory_N24diaoyu_90050501_16_dialog_content = "Eu já sou um pescador, na verdade.",
  str_homestory_N24diaoyu_90050501_17_dialog_content = "Mas eu quero me juntar a um esquadrão de pescadores.",
  str_homestory_N24diaoyu_90050501_18_dialog_content = "Infelizmente, o líder do esquadrão me recusou, dizendo que estou muito deprimido.",
  str_homestory_N24diaoyu_90050501_19_dialog_content = "Estou chateado, mas não é como se eu pudesse fazer algo sobre isso.<sprite=emo_tanqi size=60 />",
  str_homestory_N24diaoyu_90050501_20_dialog_content = "O que!? Que tipo de desculpa é essa?",
  str_homestory_N24diaoyu_90050501_21_dialog_content = "Não há chance de eu deixar você assim agora que sei disso! Venha. Vou falar com o líder do esquadrão!",
  str_homestory_N24diaoyu_90050502_1_dialog_content = "Estamos aqui.",
  str_homestory_N24diaoyu_90050502_2_dialog_content = "Agora vamos ver quem se atreveu a intimidar Axelia!",
  str_homestory_N24diaoyu_90050502_3_dialog_content = "Quem está causando todo o barulho e comoção?",
  str_homestory_N24diaoyu_90050502_4_dialog_content = "Eh? O que é aquela voz familiar?",
  str_homestory_N24diaoyu_90050502_5_dialog_content = "E-espere... Fia!?<sprite=emo_yihuo size=60 />",
  str_homestory_N24diaoyu_90050502_6_dialog_content = "Oh, PlayerName.",
  str_homestory_N24diaoyu_90050502_7_dialog_content = "Como vai o concurso? Não seja um bebê chorão só porque você perdeu para outros competidores.",
  str_homestory_N24diaoyu_90050502_8_dialog_content = "De jeito nenhum! Já derrotei dois Mestres Pescadores!",
  str_homestory_N24diaoyu_90050502_9_dialog_content = "Fleur e Azure estão impressionados com minhas habilidades!",
  str_homestory_N24diaoyu_90050502_10_dialog_content = "E também superei Barton!<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050502_11_dialog_content = "(Embora Barton tenha me envergonhado primeiro.)",
  str_homestory_N24diaoyu_90050502_12_dialog_content = "Uau, estou realmente impressionado. Eu não acho que você tem isso em você, PlayerName.",
  str_homestory_N24diaoyu_90050502_13_dialog_content = "Eu ia falar mais sobre os peixes aqui para te ajudar.",
  str_homestory_N24diaoyu_90050502_14_dialog_content = "Eu realmente sou um bom pescador. Não preciso disso para vencer... Espera, não é para isso que estou aqui.",
  str_homestory_N24diaoyu_90050502_15_dialog_content = "Então por que você está aqui?",
  str_homestory_N24diaoyu_90050502_16_dialog_content = "Fia, você criou um esquadrão ou algo assim?",
  str_homestory_N24diaoyu_90050502_17_dialog_content = "com certeza sim! O Esquadrão da Casa Cheia!",
  str_homestory_N24diaoyu_90050502_18_dialog_content = "Por que você não deixou Axelia entrar?",
  str_homestory_N24diaoyu_90050502_19_dialog_content = "...",
  str_homestory_N24diaoyu_90050502_20_dialog_content = "Bem... I-Isso é porque...",
  str_homestory_N24diaoyu_90050502_21_dialog_content = "Sua personalidade realmente não se encaixa em nosso esquadrão.",
  str_homestory_N24diaoyu_90050502_22_dialog_content = "E olhe para ela! A cor da roupa dela é parecida com a que estou vestindo.",
  str_homestory_N24diaoyu_90050502_23_dialog_content = "A cor pessoal única é muito importante para os membros deste esquadrão!",
  str_homestory_N24diaoyu_90050502_24_dialog_content = "Mas você não deu a ela a chance de mostrar suas habilidades, certo?",
  str_homestory_N24diaoyu_90050502_25_dialog_content = "Você acha que é certo julgar um livro pela capa?<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050502_26_dialog_content = "Por que de repente você está ficando nervoso assim!?",
  str_homestory_N24diaoyu_90050502_27_dialog_content = "Quero dizer, existem requisitos para entrar no esquadrão. Se ela realmente tem o que é preciso, então prove!",
  str_homestory_N24diaoyu_90050502_28_dialog_content = "Vá coletar alguns minérios, madeira ou peixe! Apenas me mostre a prova primeiro!",
  str_homestory_N24diaoyu_90050502_29_dialog_content = "Não se preocupe, Axélia. Você vai reunir os minérios e madeira. Eu te ajudo com o peixe.",
  str_homestory_N24diaoyu_90050502_30_dialog_content = "Obrigada, PlayerName.",
  str_homestory_N24diaoyu_90050503_1_dialog_content = "Você tem tudo?",
  str_homestory_N24diaoyu_90050503_2_dialog_content = "Traga-os aqui! ({1}/{2})",
  str_homestory_N24diaoyu_90050503_3_dialog_content = "Oh? Obteve-os todos tão rapidamente?",
  str_homestory_N24diaoyu_90050503_4_dialog_content = "Ainda não.",
  str_homestory_N24diaoyu_90050503_5_dialog_content = "Você pode desistir a qualquer momento.",
  str_homestory_N24diaoyu_90050503_6_dialog_content = "Multar. Admito que julguei você rápido demais. Você pode ter o que é preciso para estar no time.",
  str_homestory_N24diaoyu_90050503_7_dialog_content = "Que ótima notícia, Axelia.",
  str_homestory_N24diaoyu_90050503_8_dialog_content = "Obrigado por me ajudar, PlayerName.",
  str_homestory_N24diaoyu_90050503_9_dialog_content = "<sprite=emo_wuzui size=60 />Espere. Fez PlayerName ajudá-lo a reuni-los?",
  str_homestory_N24diaoyu_90050503_10_dialog_content = "Sim. E daí?",
  str_homestory_N24diaoyu_90050503_11_dialog_content = "<sprite=emo_shengqi size=60 />E daí? É um teste para Axelia!",
  str_homestory_N24diaoyu_90050503_12_dialog_content = "Como pode contar se você a ajudou!?",
  str_homestory_N24diaoyu_90050503_13_dialog_content = "Você nem se incomodou quando pedi sua ajuda mais cedo, e agora você está com o coração sangrando!?",
  str_homestory_N24diaoyu_90050503_14_dialog_content = "Você é simplesmente irritante!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050503_15_dialog_content = "E-espere, Fia! Achei que você tinha dito que tinha me perdoado antes!",
  str_homestory_N24diaoyu_90050503_16_dialog_content = "Eu te perdoei temporariamente! Não deixe isso para trás!",
  str_homestory_N24diaoyu_90050503_17_dialog_content = "Humph! Parece que preciso te colocar no seu lugar, PlayerName!",
  str_homestory_N24diaoyu_90050503_18_dialog_content = "Vamos fazer do jeito que fazemos entre dois Pescadores!",
  str_homestory_N24diaoyu_90050503_19_dialog_content = "Pegue sua vara de pescar e não pense que vou pegar leve com você desta vez!",
  str_homestory_N24diaoyu_90050503_20_dialog_content = "Eu vou fazer você implorar e chorar!",
  str_homestory_N24diaoyu_90050503X1_1_dialog_content = "seu estúpido PlayerName! Venha aqui para que eu possa vencê-lo!",
  str_homestory_N24diaoyu_90050503X1_2_option_content = "Eu nunca vou admitir a derrota!",
  str_homestory_N24diaoyu_90050503X1_3_option_content = "Não quero competir agora.",
  str_homestory_N24diaoyu_90050504_1_dialog_content = "<sprite=emo_hanshui size=60 />Huff... huff... Fia é bom mesmo.",
  str_homestory_N24diaoyu_90050504_2_dialog_content = "É isso que você realmente tem?",
  str_homestory_N24diaoyu_90050504_3_dialog_content = "Felizmente consegui vencer, por pouco. Você pode se acalmar agora?",
  str_homestory_N24diaoyu_90050504_4_dialog_content = "<sprite=emo_xinsui size=60 />Eu... eu não posso acreditar.",
  str_homestory_N24diaoyu_90050504_5_dialog_content = "Mas a honra é tudo para um pescador. Vou interpretar o que aconteceu antes como um pedido de desculpas.",
  str_homestory_N24diaoyu_90050504_6_dialog_content = "Axelia, dou-lhe as boas-vindas oficialmente como o segundo membro do esquadrão.",
  str_homestory_N24diaoyu_90050504_7_dialog_content = "Obrigado. Eu farei o meu melhor.",
  str_homestory_N24diaoyu_90050504_8_dialog_content = "(O quê? Apenas duas pessoas no esquadrão? Por que ela queria se juntar a esse tipo de esquadrão, para começar?)",
  str_homestory_N24diaoyu_90050504_9_dialog_content = "Agora isso é o que eu chamo de um bom final. Eu deveria estar no meu caminho para encontrar o próximo Mestre Pescador.",
  str_homestory_N24diaoyu_90050504_10_dialog_content = "Huh? Qual será o próximo Mestre Pescador?",
  str_homestory_N24diaoyu_90050504_11_dialog_content = "Você superou Fleur e Azure. Eu sou o único que restou.",
  str_homestory_N24diaoyu_90050504_12_dialog_content = "O que? Você é um pescador mestre? Pensei que você fosse o instrutor.",
  str_homestory_N24diaoyu_90050504_13_dialog_content = "Quem disse que um instrutor não pode ser um Mestre Pescador?<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050504_14_dialog_content = "Me bater sem ao menos saber disso? Você realmente é irritante, sabia?",
  str_homestory_N24diaoyu_90050504_15_dialog_content = "Venha! Vamos mais algumas rodadas!",
  str_homestory_N24diaoyu_90050601_1_dialog_content = "Minhas mãos estão tão doloridas. <sprite=emo_xuanyun size=60 />Arrastado para a pesca por Fia por mais de dez horas seguidas...",
  str_homestory_N24diaoyu_90050601_2_dialog_content = "Mas eu superei três Mestres Pescadores! PlayerName o Dragonwave Angler triunfa novamente!",
  str_homestory_N24diaoyu_90050601_3_dialog_content = "Hahaha! Agora devo conseguir a vara de pescar premiada, vendê-la e conseguir o dinheiro para construir um museu!",
  str_homestory_N24diaoyu_90050601_4_dialog_content = "Eu tenho competido com outras pessoas por tanto tempo. Quase esqueci o prazer de pescar sozinho.",
  str_homestory_N24diaoyu_90050601_5_dialog_content = "Deixe-me fazer isso então, apenas para relaxar.",
  str_homestory_N24diaoyu_90050601_6_dialog_content = "<sprite=emo_wuzui size=60 />Hum!? Essa força!",
  str_homestory_N24diaoyu_90050601_7_dialog_content = "Um peixe incrível acabou de morder a isca!",
  str_homestory_N24diaoyu_90050601_8_dialog_content = "Hehe!!",
  str_homestory_N24diaoyu_90050601_9_dialog_content = "<sprite=emo_baimao size=60 />Hum... Miau.",
  str_homestory_N24diaoyu_90050601_10_dialog_content = "O-O que...",
  str_homestory_N24diaoyu_90050601_11_dialog_content = "Philyshy!? Quão!?",
  str_homestory_N24diaoyu_90050601_12_dialog_content = "Ou este é um tipo de peixe que se assemelha a Philyshy?",
  str_homestory_N24diaoyu_90050601_13_dialog_content = "O-Ouch! Isso dói, PlayerName! Sou eu, Philyshy! Miau!<sprite=emo_baimao size=60 />",
  str_homestory_N24diaoyu_90050601_14_dialog_content = "Mas... Por que você seria pego por mim como um peixe?",
  str_homestory_N24diaoyu_90050601_15_dialog_content = "Isso importa agora? Depressa, miau! Entregue este documento para a Policial Vivian para mim!",
  str_homestory_N24diaoyu_90050602_1_dialog_content = "Oficial Vivian!",
  str_homestory_N24diaoyu_90050602_2_dialog_content = "PlayerName? Por que você está com tanta pressa?",
  str_homestory_N24diaoyu_90050602_3_dialog_content = "T-Isto! Philyshy me pediu para entregar isso a você o mais rápido possível.",
  str_homestory_N24diaoyu_90050602_4_dialog_content = "Huh? Philyshy, você diz?",
  str_homestory_N24diaoyu_90050602_5_dialog_content = "Deixe-me ver... Hmm, isso deveria estar na minha mesa ontem.",
  str_homestory_N24diaoyu_90050602_6_dialog_content = "<sprite=emo_shengqi size=60 />Philyshy... Às vezes eu realmente me pergunto o que ela tem feito.",
  str_homestory_N24diaoyu_90050602_7_dialog_content = "Hum... Tem algo que não sei se devo dizer ou não.",
  str_homestory_N24diaoyu_90050602_8_dialog_content = "Encontrei-a quando estava pescando.",
  str_homestory_N24diaoyu_90050602_9_dialog_content = "Ela está relaxando e pescando!?",
  str_homestory_N24diaoyu_90050602_10_dialog_content = "Não não. Como devo colocá-lo? Não que ela estivesse pescando.",
  str_homestory_N24diaoyu_90050602_11_dialog_content = "Eu a tirei da água...",
  str_homestory_N24diaoyu_90050602_12_dialog_content = "...",
  str_homestory_N24diaoyu_90050602_13_dialog_content = "Não importa. PlayerName, você poderia, por favor, voltar para Philyshy e dizer a ela para vir aqui?",
  str_homestory_N24diaoyu_90050603_1_dialog_content = "Philyshy, estou de volta.",
  str_homestory_N24diaoyu_90050603_2_dialog_content = "Você entregou o documento para a Policial Vivian? Obrigado! Miau!",
  str_homestory_N24diaoyu_90050603_3_dialog_content = "Mas ainda não entendo por que você estava na água e acabou do outro lado da minha vara de pescar.",
  str_homestory_N24diaoyu_90050603_4_dialog_content = "Bem... eu provavelmente estava tentando pescar, relaxando... ou sonhando acordado.",
  str_homestory_N24diaoyu_90050603_5_dialog_content = "N-Não que isso importe, miau.",
  str_homestory_N24diaoyu_90050603_6_dialog_content = "Ouvi dizer que você superou três Mestres Pescadores, PlayerName.",
  str_homestory_N24diaoyu_90050603_7_dialog_content = "Você já ouviu isso?",
  str_homestory_N24diaoyu_90050603_8_dialog_content = "Vamos lá, eu sou um oficial de inteligência, miau.<sprite=emo_emo size=60 />",
  str_homestory_N24diaoyu_90050603_9_dialog_content = "Isso mesmo. Eu derrotei três Mestres Pescadores, então sou o campeão!",
  str_homestory_N24diaoyu_90050603_10_dialog_content = "<sprite=emo_yihuo size=60 />Huh? Mas você ainda não superou o campeão.",
  str_homestory_N24diaoyu_90050603_11_dialog_content = "O que? Achei que ganharia automaticamente o evento depois de derrotar os três Mestres Pescadores.",
  str_homestory_N24diaoyu_90050603_12_dialog_content = "Claro que não, miau!",
  str_homestory_N24diaoyu_90050603_13_dialog_content = "Você tem que derrotar o campeão anterior!",
  str_homestory_N24diaoyu_90050603_14_dialog_content = "Hum... Ninguém se preocupou em me dizer isso.",
  str_homestory_N24diaoyu_90050603_15_dialog_content = "Nossa.",
  str_homestory_N24diaoyu_90050603_16_dialog_content = "Bem, para agradecer por me ajudar, vou te dizer onde você pode encontrar o campeão.",
  str_homestory_N24diaoyu_90050603_17_dialog_content = "Obrigada!",
  str_homestory_N24diaoyu_90050603_18_dialog_content = "A propósito, a policial Vivian está procurando por você.",
  str_homestory_N24diaoyu_90050603_19_dialog_content = "*Soluços* Eu sei, miau... Ainda não consigo evitá-la, posso?",
  str_homestory_N24diaoyu_90050604_1_dialog_content = "Huh...? Bereta? Você é o atual campeão?",
  str_homestory_N24diaoyu_90050604_2_dialog_content = "Você está falando sobre o concurso de pesca?",
  str_homestory_N24diaoyu_90050604_3_dialog_content = "Eu me lembro de ter feito isso, claro...",
  str_homestory_N24diaoyu_90050604_4_dialog_content = "A pesca é divertida e acho que superei algumas centenas de outros pescadores sem que eu realmente soubesse.",
  str_homestory_N24diaoyu_90050604_5_dialog_content = "E então, de alguma forma, me tornei o campeão, não que eu me importe com um título como esse.<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050604_5X1_dialog_content = "Então, você está aqui para me desafiar?",
  str_homestory_N24diaoyu_90050604_6_dialog_content = "Hum... Dizer como se não fosse nada, o melhor é sempre assim, eu acho.",
  str_homestory_N24diaoyu_90050604_7_option_content = "Vamos ver quem é melhor entre nós!",
  str_homestory_N24diaoyu_90050604_8_option_content = "Preciso fazer mais preparativos.",
  str_homestory_N24diaoyu_90050605_1_dialog_content = "<sprite=emo_daomei size=60 />Huh...! Como isso é possível?",
  str_homestory_N24diaoyu_90050605_2_dialog_content = "Você é muito bom, PlayerName. Acho que tenho que te levar mais a sério.",
  str_homestory_N24diaoyu_90050605_3_dialog_content = "Não há competição alguma. Os peixes vão para Beretta como se ela fosse um ímã de peixes ou algo assim.",
  str_homestory_N24diaoyu_90050605_4_dialog_content = "Não tem como eu ganhar.",
  str_homestory_N24diaoyu_90050605_5_dialog_content = "É este o fim da minha série de vitórias...?<sprite=emo_xinsui size=60 />",
  str_homestory_N24diaoyu_90050605_6_dialog_content = "PlayerName, você não está desistindo já, está?",
  str_homestory_N24diaoyu_90050605_7_dialog_content = "Esqueceu-se da nossa promessa?",
  str_homestory_N24diaoyu_90050605_8_dialog_content = "Vice! Carleen!",
  str_homestory_N24diaoyu_90050605_9_dialog_content = "PlayerName, continue assim! Vou preparar um banquete de frutos do mar para você se ganhar!",
  str_homestory_N24diaoyu_90050605_10_dialog_content = "Ei, parecer derrotado não é uma boa aparência para o meu pequeno celestita. Engula!",
  str_homestory_N24diaoyu_90050605_11_dialog_content = "Vamos! Você me superou, PlayerName. Não tem como você perder para ela!",
  str_homestory_N24diaoyu_90050605_12_dialog_content = "<sprite=emo_daku size=60 />Fleur... Azure... e Fia... Estão todos aqui.",
  str_homestory_N24diaoyu_90050605_13_dialog_content = "Nós não vamos te perdoar se você desistir assim, PlayerName!",
  str_homestory_N24diaoyu_90050605_14_dialog_content = "É isso! Vou levar você para a academia comigo, PlayerName. Acabei de fazer alguns halteres!",
  str_homestory_N24diaoyu_90050605_15_dialog_content = "Barton, você também...",
  str_homestory_N24diaoyu_90050605_16_dialog_content = "Obrigado por estarem aqui para mim, todos.<sprite=emo_woshou size=60 />",
  str_homestory_N24diaoyu_90050605_17_dialog_content = "Por que você está me fazendo parecer o chefe vilão final...?",
  str_homestory_N24diaoyu_90050605_18_dialog_content = "Ei! Você não está me ignorando, está?<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050605_19_dialog_content = "Obrigado a todos... por torcerem por mim!",
  str_homestory_N24diaoyu_90050605_20_dialog_content = "Agora, deixe-me mostrar a você a primeira e última habilidade final do Dragonwave Angler!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050605X_1_dialog_content = "Você quer me desafiar de novo? Eu realmente não me importo.",
  str_homestory_N24diaoyu_90050605X_2_option_content = "Para nossos companheiros!",
  str_homestory_N24diaoyu_90050605X_3_option_content = "Só mais um pouco!",
  str_homestory_N24diaoyu_90050606_1_dialog_content = "Oh... Então é assim que é perder...",
  str_homestory_N24diaoyu_90050606_2_dialog_content = "Eu venci... finalmente venci!",
  str_homestory_N24diaoyu_90050606_3_dialog_content = "Parabéns, PlayerName!<sprite=emo_caitiao size=60 />",
  str_homestory_N24diaoyu_90050606_4_dialog_content = "Incrível, PlayerName!",
  str_homestory_N24diaoyu_90050606_5_dialog_content = "Estou tocado.<sprite=emo_daku size=60 />",
  str_homestory_N24diaoyu_90050606_6_dialog_content = "Você realmente deu tudo o que tinha!",
  str_homestory_N24diaoyu_90050606_7_dialog_content = "Como você realmente cresceu, minha pequena celestita.<sprite=emo_aixin size=60 />",
  str_homestory_N24diaoyu_90050606_8_dialog_content = "Assim é melhor!",
  str_homestory_N24diaoyu_90050606_9_dialog_content = "<sprite=emo_sikao size=60 />Você ainda está me ignorando!?",
  str_homestory_N24diaoyu_90050606_10_dialog_content = "Obrigado... Obrigado a todos.",
  str_homestory_N24diaoyu_90050606_11_dialog_content = "Bem feito... Assim é PlayerName o novo campeão agora?",
  str_homestory_N24diaoyu_90050606_12_dialog_content = "Acontece que eu trouxe o anfitrião do evento comigo. Podemos distribuir as recompensas agora, certo?",
  str_homestory_N24diaoyu_90050606_13_dialog_content = "Bom... sobre isso...",
  str_homestory_N24diaoyu_90050606_14_dialog_content = "Jomu? Foi você quem sugeriu isso ao editor?",
  str_homestory_N24diaoyu_90050606_15_dialog_content = "Estou impressionado. Não pensei que você faria nada de graça.",
  str_homestory_N24diaoyu_90050606_16_dialog_content = "A propósito, onde está meu prêmio? Aquela vara de pescar super incrível?",
  str_homestory_N24diaoyu_90050606_17_dialog_content = "Sim, eu estava chegando a isso...",
  str_homestory_N24diaoyu_90050606_18_dialog_content = "Sabe, o preço da Lumamber disparou...",
  str_homestory_N24diaoyu_90050606_19_dialog_content = "Então eu tive que trocar as gemas na vara de pescar pelos minérios que sobraram de Brock.",
  str_homestory_N24diaoyu_90050606_20_dialog_content = "Mas é o que ela representa que importa, certo? Quero dizer, é um símbolo de sua maestria!<sprite=emo_dianzan size=60 />",
  str_homestory_N24diaoyu_90050606_21_dialog_content = "Dar...",
  str_homestory_N24diaoyu_90050606_22_dialog_content = "Dê-me minha vara de pescar Lumamber de ouro puro!!!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050901_1_dialog_content = "Ter uma competição com Carleen.",
  str_homestory_N24diaoyu_90050902_1_dialog_content = "Fantástico.",
  str_homestory_N24diaoyu_90050903_1_dialog_content = "Ela é a capitã...",
  str_homestory_N24diaoyu_90050904_1_dialog_content = "Ela parece muito zangada.",
  str_homestory_N24diaoyu_90050905_1_dialog_content = "Vamos ouvir o que ela tem a dizer primeiro.",
  str_homestory_N24diaoyu_90050906_1_dialog_content = "Não tenho tempo para explicar, miau. Leve esta informação para a Oficial Vivian para mim primeiro!",
  str_homestory_N24diaoyu_90050907_1_dialog_content = "Por favor, me ajude a ligar para Philyshy aqui.",
  str_homestory_N24diaoyu_90050908_1_dialog_content = "Como esperado de PlayerName! Você é simplesmente incrível!",
  str_homestory_N24diaoyu_90050909_1_dialog_content = "Ninguém é tão habilidoso quanto você, PlayerName.",
  str_homestory_N24diaoyu_90050910_1_dialog_content = "Brilhante!",
  str_homestory_N24diaoyu_90050911_1_dialog_content = "Eu estava certo sobre você, pequena celestita.",
  str_homestory_N24diaoyu_90050912_1_dialog_content = "Eu não quero admitir isso, mas PlayerName realmente é muito forte!",
  str_homestory_N24diaoyu_90050913_1_dialog_content = "Uau! Que competição satisfatória!",
  str_homestory_N24diaoyu_90050914_1_dialog_content = "Vamos se você terminou. Vamos nos exercitar juntos!",
  str_homestory_N24diaoyu_90050915_1_dialog_content = "Carleen!",
  str_homestory_N24diaoyu_90050915_2_dialog_content = "Huh? O que é isso, PlayerName?",
  str_homestory_N24diaoyu_90050915_3_dialog_content = "Você continua me encarando como se tivesse algo a dizer.",
  str_homestory_N24diaoyu_90050915_4_dialog_content = "Sim, eu sinto, na verdade, mas eu me sinto meio...",
  str_homestory_N24diaoyu_90050915_5_dialog_content = "Sinta-se à vontade para dizer o que quiser.",
  str_homestory_N24diaoyu_90050915_6_dialog_content = "Tá, então direi...",
  str_homestory_N24diaoyu_90050915_7_dialog_content = "Sim.",
  str_homestory_N24diaoyu_90050915_8_dialog_content = "Bom...",
  str_homestory_N24diaoyu_90050915_9_dialog_content = "O quê?",
  str_homestory_N24diaoyu_90050915_10_dialog_content = "Você tem praticado pesca em segredo, Carleen?",
  str_homestory_N24diaoyu_90050915_11_dialog_content = "... Acertou.",
  str_homestory_N24diaoyu_90050915_12_dialog_content = "Eu tenho muitas testemunhas.",
  str_homestory_N24diaoyu_90050915_13_dialog_content = "Sim. Desde a nossa última rodada, tenho aprimorado minhas habilidades.",
  str_homestory_N24diaoyu_90050915_14_dialog_content = "Depois de estudar você, PlayerName, e todos os Mestres Pescadores, sinto que aprendi muito.",
  str_homestory_N24diaoyu_90050915_15_dialog_content = "Eu diria até que agora estou bom o suficiente para estar no nível de quando você derrotou Beretta.",
  str_homestory_N24diaoyu_90050915_16_dialog_content = "Sério?",
  str_homestory_N24diaoyu_90050915_17_dialog_content = "Então, quer me experimentar?",
  str_homestory_N24diaoyu_90050915_18_dialog_content = "Claro. Você foi meu primeiro adversário e um parceiro inestimável em minha busca para ser o campeão!",
  str_homestory_N24diaoyu_90050915_19_dialog_content = "Fico feliz que você pense isso. Vamos para o rio, então.",
  str_homestory_N24diaoyu_90050916_1_dialog_content = "Devemos começar?",
  str_homestory_N24diaoyu_90050916_2_option_content = "Sim, mal posso esperar!",
  str_homestory_N24diaoyu_90050916_3_option_content = "Espere um segundo...",
  str_homestory_N24diaoyu_90050917_1_dialog_content = "Com certeza você é bom, PlayerName... Eu admito.",
  str_homestory_N24diaoyu_90050917_2_dialog_content = "Você melhorou muito, Carleen. Eu sinto que se eu escorregasse uma vez, você me venceria.",
  str_homestory_N24diaoyu_90050917_3_dialog_content = "Hum...",
  str_homestory_N24diaoyu_90050917_4_dialog_content = "Esqueça os elogios.",
  str_homestory_N24diaoyu_90050917_5_dialog_content = "Este é o polvo de anéis azuis que peguei na prática. Você pode tê-lo.",
  str_homestory_N24diaoyu_90050917_6_dialog_content = "Tem certeza que? É raro, você sabe.",
  str_homestory_N24diaoyu_90050917_7_dialog_content = "Tenho certeza. Da próxima vez que eu pegar outro é quando eu vou bater em você, PlayerName.",
  str_homestory_N24diaoyu_90050917_8_dialog_content = "Vou continuar praticando também, e ser ainda melhor da próxima vez!",
  str_homestory_N24diaoyu_90050917_9_dialog_content = "Faremos outra rodada novamente em algum momento.",
  str_homestory_N24diaoyu_90050917_10_dialog_content = "Pode deixar!",
  str_homestory_N24diaoyu_90050918_1_dialog_content = "Eu melhorei minhas habilidades ultimamente. Vamos tentar de novo.",
  str_homestory_N24diaoyu_90050918_2_option_content = "Vamos!",
  str_homestory_N24diaoyu_90050918_3_option_content = "Acabei de lembrar que tenho algo para fazer.",
  str_homestory_N24diaoyu_90050919_1_dialog_content = "Ok, te espero aqui."
}
return config
